import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyBaoTri = () => {
    const now = new Date();
    const [selectedDate, setSelectedDate] = useState(now.getDate());
    const [selectedMonth, setSelectedMonth] = useState(now.getMonth() + 1);
    const [selectedYear, setSelectedYear] = useState(now.getFullYear());

    const [loading, setLoading] = useState(false);
    const [requests, setRequests] = useState([]);

    const days = Array.from({ length: 31 }, (_, i) => i + 1);
    const months = Array.from({ length: 12 }, (_, i) => i + 1);
    const years = [2024, 2025, 2026];

    // --- PHẦN KẾT NỐI BACKEND (Fetch theo Ngày/Tháng/Năm) ---
    useEffect(() => {
        const fetchRequestsByDate = async () => {
            setLoading(true);
            try {
                // SAU NÀY: const res = await axios.get(`/api/maintenance?day=${selectedDate}&month=${selectedMonth}&year=${selectedYear}`);
                // setRequests(res.data);

                // GIẢ LẬP: Nếu chọn đúng ngày hôm nay thì hiện 1 vài mẫu, ngày khác thì trống
                setTimeout(() => {
                    if (selectedDate === now.getDate() && selectedMonth === (now.getMonth() + 1)) {
                        setRequests([
                            { id: 1, room: 'A101', issue: 'Hỏng vòi nước bồn rửa mặt', date: `${selectedDate}/${selectedMonth}/${selectedYear}`, status: 'pending' },
                            { id: 2, room: 'B202', issue: 'Cháy bóng đèn hành lang tầng 2', date: `${selectedDate}/${selectedMonth}/${selectedYear}`, status: 'processing' }
                        ]);
                    } else {
                        setRequests([]); // Các ngày khác coi như chưa có yêu cầu
                    }
                    setLoading(false);
                }, 400);
            } catch (error) {
                console.error("Lỗi lấy dữ liệu:", error);
                setLoading(false);
            }
        };
        fetchRequestsByDate();
    }, [selectedDate, selectedMonth, selectedYear]);

    const updateStatus = async (id, newStatus) => {
        setRequests(prev => prev.map(req => req.id === id ? { ...req, status: newStatus } : req));
        try {
            // await axios.put(`/api/maintenance/${id}`, { status: newStatus });
            console.log(`Backend: Cập nhật yêu cầu ${id} sang ${newStatus}`);
        } catch (error) {
            alert("Lỗi cập nhật!");
        }
    };

    const getStatusStyle = (status) => {
        switch (status) {
            case 'pending': return { label: 'Chờ xử lý', color: '#dc3545', bg: '#f8d7da', border: '#f5c6cb' };
            case 'processing': return { label: 'Đang xử lý', color: '#856404', bg: '#fff3cd', border: '#ffeeba' };
            case 'completed': return { label: 'Hoàn thành', color: '#155724', bg: '#d4edda', border: '#c3e6cb' };
            default: return { label: 'Khác', color: '#383d41', bg: '#e2e3e5', border: '#d6d8db' };
        }
    };

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden', height: 'calc(100vh - 120px)',
            boxShadow: '0 10px 40px rgba(0,0,0,0.4)'
        }} className="glass-card">

            {/* Header với bộ chọn Ngày/Tháng/Năm */}
            <div style={{ 
                padding: '20px 30px', background: 'rgba(0,0,0,0.5)', 
                display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                backdropFilter: 'blur(10px)', borderBottom: '1px solid rgba(255,255,255,0.1)'
            }}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '22px', fontWeight: 'bold' }}>
                    🛠 QUẢN LÝ YÊU CẦU BẢO TRÌ
                </h2>

                <div style={{ display: 'flex', gap: '10px' }}>
                    <select value={selectedDate} onChange={(e) => setSelectedDate(parseInt(e.target.value))} 
                        style={selectStyle}>
                        {days.map(d => <option key={d} value={d}>Ngày {d}</option>)}
                    </select>
                    <select value={selectedMonth} onChange={(e) => setSelectedMonth(parseInt(e.target.value))} 
                        style={selectStyle}>
                        {months.map(m => <option key={m} value={m}>Tháng {m}</option>)}
                    </select>
                    <select value={selectedYear} onChange={(e) => setSelectedYear(parseInt(e.target.value))} 
                        style={selectStyle}>
                        {years.map(y => <option key={y} value={y}>Năm {y}</option>)}
                    </select>
                </div>
            </div>

            {/* Nội dung danh sách */}
            <div style={{ flex: 1, padding: '25px', display: 'flex', justifyContent: 'center', overflow: 'hidden' }}>
                <div style={{ 
                    width: '100%', maxWidth: '1100px', backgroundColor: 'rgba(255, 255, 255, 0.95)', 
                    borderRadius: '25px', display: 'flex', flexDirection: 'column',
                    boxShadow: '0 8px 32px rgba(0,0,0,0.3)', overflow: 'hidden'
                }}>

                    <div style={{ flex: 1, overflowY: 'auto' }} className="custom-scrollbar">
                        {loading ? (
                            <div style={{ textAlign: 'center', padding: '100px', fontSize: '18px', color: '#8b5e5e' }}>
                                ĐANG TẢI YÊU CẦU...
                            </div>
                        ) : requests.length > 0 ? (
                            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                                <thead style={{ position: 'sticky', top: 0, backgroundColor: '#f1f1f1', zIndex: 10 }}>
                                    <tr style={{ textAlign: 'left', borderBottom: '2px solid #dee2e6' }}>
                                        <th style={{ padding: '20px' }}>PHÒNG</th>
                                        <th style={{ padding: '20px' }}>NỘI DUNG SỰ CỐ</th>
                                        <th style={{ padding: '20px' }}>THỜI GIAN</th>
                                        <th style={{ padding: '20px' }}>TRẠNG THÁI</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {requests.map((req) => {
                                        const style = getStatusStyle(req.status);
                                        return (
                                            <tr key={req.id} style={{ borderBottom: '1px solid #eee' }} className="row-hover">
                                                <td style={{ padding: '20px', fontWeight: '800', fontSize: '20px' }}>{req.room}</td>
                                                <td style={{ padding: '20px', color: '#444' }}>{req.issue}</td>
                                                <td style={{ padding: '20px', color: '#888', fontSize: '14px' }}>{req.date}</td>
                                                <td style={{ padding: '20px' }}>
                                                    <select 
                                                        value={req.status} 
                                                        onChange={(e) => updateStatus(req.id, e.target.value)}
                                                        style={{ 
                                                            padding: '8px 12px', borderRadius: '10px', border: `1px solid ${style.border}`,
                                                            backgroundColor: style.bg, color: style.color, fontWeight: 'bold', cursor: 'pointer'
                                                        }}
                                                    >
                                                        <option value="pending">⏳ Chờ xử lý</option>
                                                        <option value="processing">🛠 Đang xử lý</option>
                                                        <option value="completed">✅ Hoàn thành</option>
                                                    </select>
                                                </td>
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        ) : (
                            <div style={{ textAlign: 'center', padding: '100px', color: '#bbb' }}>
                                <div style={{ fontSize: '60px', marginBottom: '10px' }}>📅</div>
                                <p style={{ fontSize: '18px' }}>Không có yêu cầu bảo trì nào trong ngày {selectedDate}/{selectedMonth}/{selectedYear}</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 6px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.1); border-radius: 10px; }
                .row-hover:hover { background-color: #f8f9fa; }
            `}</style>
        </div>
    );
};

// Style cho các ô Select ở Header
const selectStyle = {
    padding: '8px 12px',
    borderRadius: '12px',
    border: 'none',
    backgroundColor: 'rgba(255,255,255,0.9)',
    fontWeight: 'bold',
    cursor: 'pointer',
